and ocort.page_no = #{page_no}
LIMIT #{size} OFFSET #{offset}

SELECT ocot.*, ROW_NUMBER() OVER (ORDER BY ocot.resource_type, ocot.resource_name) AS row_no FROM om_cloud_optimizer_tbl ocot WHERE 1 = 1
AND ocot.resource_type > 0
AND ocot.resource_parent_no = #{resource_parent_no}
AND org_time > 0 AND new_time > 0
LIMIT #{size} OFFSET #{offset}

