mapper.select:
SELECT ocot.*
FROM om_cloud_optimizer_tbl ocot
LEFT JOIN (
    SELECT ocrlt.resource_no,  sum(cnt) AS call_cnt
    FROM public.om_resource_call_cnt_month ocrlt
    WHERE ocrlt.resource_no = #{resource_no}
    GROUP BY ocrlt.resource_no
) cc ON ocot.resource_no = cc.resource_no
WHERE ocot.resource_no = #{resource_no};

