	AND resource_status = #{resource_status}

ORDER BY resource_org;

SELECT *,
	ROW_NUMBER() OVER (ORDER BY CASE ocot.resource_status
			WHEN 0 THEN 1
			WHEN 1 THEN 2
			WHEN 2 THEN 3
			ELSE 4
			END, ocot.resource_org) AS row_no,
	(SELECT  sum(cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no) AS call_cnt		
FROM om_cloud_optimizer_tbl ocot
WHERE 1 = 1 
	AND resource_type = #{resource_type} 

		AND resource_status = #{resource_status}


		AND resource_org_size > 0


		AND resource_org_size  <  0







					ORDER BY ocot.resource_type ${sortItem.dir} 


					ORDER BY ocot.resource_name ${sortItem.dir} 


					ORDER BY ocot.resource_type, ocot.resource_status ${sortItem.dir} 


					ORDER BY ocot.resource_type, ocot.resource_new_size_type1 ${sortItem.dir} 


					ORDER BY ocot.resource_type, ocot.resource_new_size_type2 ${sortItem.dir} 


					ORDER BY ocot.resource_type, ocot.call_cnt ${sortItem.dir} 





		ORDER BY CASE resource_status
			WHEN 0 THEN 1
			WHEN 1 THEN 2
			WHEN 2 THEN 3
			ELSE 4
			END, resource_org


		ORDER BY resource_org



	LIMIT #{size} OFFSET #{offset}

SELECT * FROM om_cloud_optimizer_tbl ocot
WHERE resource_type = #{resource_type}
	AND resource_org_size > 0

SELECT rgstr_date, count(*) FROM om_cloud_resource_log_tbl ocrlt  
WHERE resource_no = #{resource_no}
GROUP BY rgstr_date

SELECT resource_type, COUNT(*) AS total, (SELECT COUNT(*) FROM om_cloud_optimizer_tbl ocot2 where ocot.resource_type = ocot2.resource_type AND ocot2.resource_status = 1
) AS status1_count, (SELECT COUNT(*) FROM om_cloud_optimizer_tbl ocot2 where ocot.resource_type = ocot2.resource_type AND ocot2.resource_status = -1 AND resource_new_size_type1 != -1
) AS status_minus_count FROM om_cloud_optimizer_tbl ocot WHERE 1 = 1
GROUP BY resource_type

mapper.sql:
WITH latest_log AS ( SELECT resource_no, rgstr_dt, resource_log_content, row_number() OVER (PARTITION BY resource_no ORDER BY rgstr_dt DESC) AS rn FROM om_cloud_optimizer_log_tbl WHERE rgstr_dt <=
#{endDate_ts}
NOW()
), current_month AS ( SELECT resource_no, COUNT(*) AS current_month_count FROM om_cloud_optimizer_log_tbl WHERE date_trunc('month', rgstr_dt) = date_trunc('month', now()) GROUP BY resource_no ), previous_month AS ( SELECT resource_no, COUNT(*) AS previous_month_count FROM om_cloud_optimizer_log_tbl WHERE date_trunc('month', rgstr_dt) = date_trunc('month', now() - interval '1 month') GROUP BY resource_no ), resource_counts AS ( SELECT resource_no, COUNT(*) AS count_records FROM om_cloud_optimizer_log_tbl GROUP BY resource_no )

mapper.select:
SELECT ocot.*, ROW_NUMBER() OVER (ORDER BY ocot.resource_type, ocot.resource_name) AS row_no, ocolt.rgstr_dt as log_rgstr_dt, ocolt.resource_log_content, COALESCE(cm.current_month_count, 0) AS current_month_call_count, COALESCE(pm.previous_month_count, 0) AS previous_month_call_count FROM om_cloud_optimizer_tbl ocot INNER JOIN latest_log ocolt ON ocot.resource_no = ocolt.resource_no AND ocolt.rn = 1 AND ocolt.resource_log_content = '1' LEFT JOIN current_month cm ON ocot.resource_no = cm.resource_no LEFT JOIN previous_month pm ON ocot.resource_no = pm.resource_no WHERE 1 = 1
AND ocot.resource_type > 0
AND ocot.resource_parent_no = #{resource_parent_no}
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE om_cloud_optimizer_tbl 
SET resource_condition = #{resource_condition}
WHERE resource_no = #{resource_no}

mapper.select:
SELECT ocot.*, ROW_NUMBER() OVER (ORDER BY ocot.resource_type, ocot.resource_name) AS row_no, (SELECT SUM(ocrlt.cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no and yyyy = EXTRACT(YEAR FROM CURRENT_DATE) AND mm = EXTRACT(MONTH FROM CURRENT_DATE) ) AS current_month_call_count, (SELECT SUM(ocrlt.cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no and yyyy = EXTRACT(YEAR FROM CURRENT_DATE - INTERVAL '1 month') AND mm = EXTRACT(MONTH FROM CURRENT_DATE - INTERVAL '1 month') ) AS previous_month_call_count, (SELECT SUM(ocrlt.opt_cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no and yyyy = EXTRACT(YEAR FROM CURRENT_DATE) AND mm = EXTRACT(MONTH FROM CURRENT_DATE) ) AS current_month_opt_count, (SELECT SUM(ocrlt.opt_cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no and yyyy = EXTRACT(YEAR FROM CURRENT_DATE - INTERVAL '1 month') AND mm = EXTRACT(MONTH FROM CURRENT_DATE - INTERVAL '1 month') ) AS previous_month_opt_count, (SELECT SUM(ocrlt.total_optimized_traffic) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no and yyyy = EXTRACT(YEAR FROM CURRENT_DATE - INTERVAL '1 month') AND mm = EXTRACT(MONTH FROM CURRENT_DATE - INTERVAL '1 month') ) AS pre_total_optimized_traffic, (SELECT SUM(ocrlt.total_optimized_traffic) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no and yyyy = EXTRACT(YEAR FROM CURRENT_DATE) AND mm = EXTRACT(MONTH FROM CURRENT_DATE) ) AS current_total_optimized_traffic FROM om_cloud_optimizer_tbl ocot WHERE 1 = 1
AND ocot.resource_type > 0
AND ocot.resource_parent_no = #{resource_parent_no}
LIMIT #{size} OFFSET #{offset}

SELECT ocort.page_no, ROUND(SUM(ocot.org_time), 1) AS org_time, ROUND( SUM( CASE WHEN ocot.new_time IS NULL OR ocot.new_time = 0 THEN ocot.org_time ELSE ocot.new_time END ), 1) AS new_time, ROUND( CASE WHEN SUM(ocot.org_time) = 0 THEN NULL ELSE (ROUND(SUM(ocot.org_time), 1) - ROUND( SUM( CASE WHEN ocot.new_time IS NULL OR ocot.new_time = 0 THEN ocot.org_time ELSE ocot.new_time END ), 1)) / ROUND(SUM(ocot.org_time), 1) * 100 END, 1) AS percent, (SELECT site_address FROM om_cloud_site_tbl ocst WHERE 1=1
AND site_no IN
CAST(#{item} AS INTEGER)
) AS site_address, (SELECT page_url FROM om_cloud_optimizer_page_tbl WHERE page_no = ocort.page_no) AS page_url, (SELECT page_path FROM om_cloud_optimizer_page_tbl WHERE page_no = ocort.page_no) AS page_path FROM om_cloud_optimizer_tbl ocot JOIN om_cloud_optimizer_rel_tbl ocort ON ocot.resource_no = ocort.resource_no WHERE 1=1 and page_no = #{page_no}
AND ocot.site_no IN
CAST(#{item} AS INTEGER)
AND ocot.resource_type > 0
and resource_type = #{resource_type}
GROUP BY ocort.page_no;

mapper.update:

UPDATE om_cloud_optimizer_tbl
SET resource_status = ${resource_status}, algorithm_sn = CAST(NULLIF(resource_type1, '') AS INTEGER)
WHERE resource_no IN (
  SELECT resource_no
  FROM om_cloud_optimizer_rel_tbl
  WHERE page_no = ${page_no}
);

mapper.select:
SELECT ocot.*, ROW_NUMBER() OVER (ORDER BY ocot.resource_type, ocot.resource_name) AS row_no, (SELECT SUM(ocrlt.cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no AND yyyy = EXTRACT(YEAR FROM CURRENT_DATE) AND mm = EXTRACT(MONTH FROM CURRENT_DATE) AND dd <= EXTRACT(DAY FROM CURRENT_DATE) ) AS current_month_call_count, (SELECT SUM(ocrlt.cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no AND yyyy = EXTRACT(YEAR FROM CURRENT_DATE - INTERVAL '1 month') AND mm = EXTRACT(MONTH FROM CURRENT_DATE - INTERVAL '1 month') AND dd <= EXTRACT(DAY FROM CURRENT_DATE) ) AS previous_month_call_count, (SELECT SUM(ocrlt.opt_cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no AND yyyy = EXTRACT(YEAR FROM CURRENT_DATE) AND mm = EXTRACT(MONTH FROM CURRENT_DATE) AND dd <= EXTRACT(DAY FROM CURRENT_DATE) ) AS current_month_opt_count, (SELECT SUM(ocrlt.opt_cnt) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no AND yyyy = EXTRACT(YEAR FROM CURRENT_DATE - INTERVAL '1 month') AND mm = EXTRACT(MONTH FROM CURRENT_DATE - INTERVAL '1 month') AND dd <= EXTRACT(DAY FROM CURRENT_DATE) ) AS previous_month_opt_count, (SELECT SUM(ocrlt.total_optimized_traffic) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no AND yyyy = EXTRACT(YEAR FROM CURRENT_DATE - INTERVAL '1 month') AND mm = EXTRACT(MONTH FROM CURRENT_DATE - INTERVAL '1 month') AND dd <= EXTRACT(DAY FROM CURRENT_DATE) ) AS pre_total_optimized_traffic, (SELECT SUM(ocrlt.total_optimized_traffic) FROM public.om_resource_call_cnt_month ocrlt WHERE ocrlt.resource_no = ocot.resource_no AND yyyy = EXTRACT(YEAR FROM CURRENT_DATE) AND mm = EXTRACT(MONTH FROM CURRENT_DATE) AND dd <= EXTRACT(DAY FROM CURRENT_DATE) ) AS current_total_optimized_traffic FROM om_cloud_optimizer_tbl ocot WHERE 1 = 1
AND ocot.resource_type > 0
AND ocot.resource_parent_no = #{resource_parent_no}
LIMIT #{size} OFFSET #{offset}
